export function VirtualList({
  heading = "{{heading}}",
  accent = "{{accent}}",
  windowSize = "{{windowSize}}",
  rowHeight = {{rowHeight}},
  rendered = {{rendered}},
}) {
  const names = ["Alicia Ferreira", "Ben Sato", "Charu Deshpande", "Diego Morales", "Erin Walsh", "Femi Adeyemi", "Grace Kim"].slice(0, Number(windowSize));
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 300, width: 300, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <p style={{ margin: "0 0 10px", fontSize: 12, color: "#241430a0" }}>Only the rows in view are kept in the DOM; the scrollbar tracks the full list.</p>
      <div style={{ maxHeight: 176, overflow: "auto", position: "relative", border: "1px solid #24143020", borderRadius: 8 }}>
        <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
          {names.map((name) => (
            <li key={name} style={{ display: "flex", alignItems: "center", height: rowHeight, padding: "0 10px", borderBottom: "1px solid #24143014", borderLeft: `3px solid ${accent}`, background: "#fff" }}>{name}</li>
          ))}
        </ul>
        <div aria-hidden="true" style={{ height: 900, background: "repeating-linear-gradient(180deg, #24143008 0 1px, transparent 1px 34px)" }} />
      </div>
      <p role="status" style={{ margin: "10px 0 0", fontSize: 12, color: "#241430a0" }}>{rendered} of 2,400 rows exist in the DOM right now.</p>
    </div>
  );
}
